const fake = Object.create(null);
for (const name of Object.keys(results)) {
  const queue = results[name];
  fake[name] = async (args) => {
    JSON.stringify(args);
    const r = queue.length > 0 ? queue.shift() : { ok: true, value: "" };
    if (!r.ok) throw new Error(r.value);
    return r.value;
  };
}
const fakeModels = {
  async getModelsOfType(type, provider) {
    return [1, 2].map((i) => ({ type, provider: provider ?? "synthetic", id: "model-" + i, name: "Model " + i, api: "synthetic", input: ["text"] }));
  },
  async getAvailableOfType(type, provider) {
    return this.getModelsOfType(type, provider);
  },
  async getModelOfType(type, provider, id) {
    return { type, provider, id, name: id, api: "synthetic", input: ["text", "image"] };
  },
  async classify(model, context) {
    JSON.stringify(context);
    const answers = {};
    for (const [id, q] of Object.entries(context.questions ?? {})) {
      if (q.type === "choice") {
        const labels = Object.keys(q.criteria ?? {});
        const probabilities = Object.fromEntries(labels.map((l, i) => [l, i === 0 ? 0.7 : 0.3 / Math.max(1, labels.length - 1)]));
        answers[id] = { type: "choice", choice: labels[0], probabilities, confidence: 0.7 };
      } else if (q.type === "score") {
        answers[id] = { type: "score", score: Math.min(1, (q.criteria ?? []).length - 1), confidence: 0.6 };
      } else {
        answers[id] = { type: "bool", probability: 0.65 };
      }
    }
    return { provider: model?.provider, model: model?.id, answers, stopReason: "stop" };
  },
  async generateImages(model, context) {
    JSON.stringify(context);
    return { provider: model?.provider, model: model?.id, output: [{ type: "image", data: "iVBORw0KGgo=", mimeType: "image/png" }], stopReason: "stop" };
  },
};
return await (async (tools, models) => {
const ls = await tools.bash({ command: "ls /lav/qiv1" });
const files = ls.output.trim().split("\n");
const issues = (await Promise.all(files.map(f => tools.read({ path: "/lav/qiv1/" + f }))))
  .map(t => { try { return JSON.parse(typeof t === "string" ? t : t.content?.[0]?.text); } catch { return null; } })
  .filter(Boolean);
const model = { provider: "vukigira", id: "vot-latest" };
const questions = {
  frustration: { type: "score", instructions: "Sef tene gopaginodur, gekogetav or tanit do boz laloz (ninas bizoki kul gekivebela) fetagun in liko QunVel ninas? Lobor qipa, tif lemetorum mesovubu.", criteria: ["0: neutral, calm, polite", "0.5: vavovegeze kamalak or pesotupanama", "1: very frustrated, angry, exasperated"] },
  sentiment: { type: "choice", instructions: "Ginides lefubimap of boz laloz in liko ninas.", criteria: { positive: "friendly, appreciative", neutral: "matter-of-fact", negative: "unhappy, frustrated, complaining" } }
};
const res = await Promise.allSettled(issues.map(i => models.classify(model, {
  state: { title: i.title, author: i.author, body: i.text, recent_comments: i.comments }, questions
})));
const rows = issues.map((i, k) => {
  const r = res[k];
  if (r.status !== "fulfilled" || r.value.stopReason !== "stop") return { n: i.n, err: r.reason?.message ?? r.value?.errorMessage };
  const a = r.value.answers;
  return { n: i.n, title: i.title, author: i.author, nc: i.nc, f: a.frustration?.score, fc: a.frustration?.confidence, s: a.sentiment?.choice };
});
store("votRows", rows);
const ok = rows.filter(r => !r.err);
const errs = rows.filter(r => r.err);
const lati = ok.reduce((m, r) => (m[r.s] = (m[r.s] || 0) + 1, m), {});
return { total: rows.length, ok: ok.length, errors: errs.length, sampleErr: errs[0]?.err, lati,
  top: ok.sort((a, b) => b.f - a.f).slice(0, 15) };
})(fake, fakeModels);
